// PWM: the switches set the brightness of an LED on Pmod JB.
module top #(
  parameter CLK_HZ = 100_000_000
) (
  input         clk,
  input  [15:0] sw,     // SW7-SW0 set the brightness, 0-255
  output [7:0]  JB,     // Pmod JB: JB[0] is pin 1
  output [15:0] led
);
  // A free-running 8-bit counter: 0, 1, ... 255, 0, ...
  reg [7:0] ramp = 0;
  always @(posedge clk) ramp <= ramp + 1;

  // High while the ramp is below the switch value.
  wire bright = ramp < sw[7:0];

  // A one-second heartbeat on LD15, timed from CLK_HZ.
  localparam HALF = CLK_HZ / 2;
  reg [31:0] count = 0;
  reg        beat  = 1'b0;
  always @(posedge clk) begin
    if (count == HALF - 1) begin
      count <= 0;
      beat  <= ~beat;
    end else
      count <= count + 1;
  end

  assign JB  = {7'b0, bright};           // only JB pin 1 is used; the rest stay low
  assign led = {beat, 14'b0, bright};
endmodule

